class TrieNode:
    def __init__(self):
        self.children = {}
        self.word = None  # Stores full word at terminal node

def build_trie(words):
    root = TrieNode()
    for word in words:
        node = root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.word = word  # Mark the end of a word
    return root

def findWords(board, words):
    def dfs(node, i, j):
        letter = board[i][j]
        if letter not in node.children:
            return

        next_node = node.children[letter]
        if next_node.word:
            res.add(next_node.word)
            next_node.word = None  # To avoid duplicates

        board[i][j] = "#"  # Mark visited
        for dx, dy in [(-1,0),(1,0),(0,-1),(0,1)]:
            ni, nj = i + dx, j + dy
            if 0 <= ni < m and 0 <= nj < n and board[ni][nj] != "#":
                dfs(next_node, ni, nj)
        board[i][j] = letter  # Unmark

    # Initialize
    m, n = len(board), len(board[0]) if board else 0
    root = build_trie(words)
    res = set()

    for i in range(m):
        for j in range(n):
            dfs(root, i, j)

    return list(res)
